"""Auto-generated README documentation for output roots and product folders per ADR 0016."""

from __future__ import annotations

import json
from pathlib import Path

from dubanevics2026topological.results.manifest import Manifest, read_manifest

PRODUCT_DESCRIPTIONS: dict[str, str] = {
    "fitness": (
        "Functional sequence classifications, point estimates, pooled standard errors, "
        "and multiple-testing adjusted q-values."
    ),
    "pooled_scatter": (
        "Pooled-standard-error scatter tables (with wild type) for the peak-uncertainty "
        "figure, derived from the verified growth-rates parent and the legacy peak checkpoint."
    ),
    "threshold_diagnostics": (
        "Candidate and reflected functional thresholds (with unrounded T), median, "
        "global minimum, median gap, and trailing saddle deaths for the full graph."
    ),
    "landscape": (
        "Selected genotype networks, connected components, nominal merge trees, "
        "and ordinary H0 persistence pairs. A product labelled graph=full is accepted "
        "only when every input vertex and edge is retained in one connected component; "
        "its manifest records the input and selected counts."
    ),
    "bootstrap": (
        "Stability distributions, perturbation bottleneck distance quantiles, and draw metadata "
        "from fixed-graph bootstrap resampling."
    ),
    "tree": (
        "Topological merge trees, including unsimplified nominal trees and direct "
        "persistence-band simplified trees."
    ),
    "tree_layout": (
        "Presentation geometry and marker positions for an identified tree state."
    ),
    "tree_annotations": (
        "Sequence-keyed biological annotations for an identified tree state."
    ),
    "leaves": (
        "Per-leaf tables with sequence compositions, synonymous mutation status, and "
        "root-endpoint indicators."
    ),
    "landscape_summary": (
        "Multi-treatment topological summary tables across graph treatments and persistence layers."
    ),
    "ridges": (
        "Superlevel component and ridge sequence memberships connecting topological peaks."
    ),
    "ridge_entropy_sweeps": (
        "Positional codon entropy sweeps and populations of the core, KEM and TCL "
        "ridges of one band-simplified tree."
    ),
    "merge_flow": (
        "Merge-flow components, merge events and per-level functional counts of one "
        "merge tree, keyed by sequence."
    ),
}


def generate_root_readme(_output_root: Path | str | None = None) -> str:
    """Generate README.md content for an output root directory."""
    lines = [
        "# FitnessTree Analysis Outputs",
        "",
        "This directory contains standardized scientific data products generated by the FitnessTree",
        "topological analysis pipeline per ADR 0016 (result labels and file naming).",
        "",
        "## Product Folders",
        "",
    ]

    for product_type, desc in sorted(PRODUCT_DESCRIPTIONS.items()):
        lines.append(f"### `{product_type}/`")
        lines.append(f"{desc}")
        lines.append("")

    lines.extend(
        [
            "## Storage and Naming Conventions",
            "",
            "- **DrWatson Parameter Labels**: Folders follow `<product>__<params>_hash=<8hex>`.",
            "- **Immutable Manifests**: Every run folder contains a `manifest.json` recording",
            "  the cryptographic `scientific_id_sha256`, upstream parent hashes, full parameters,",
            "  software environment, and artifact checksums.",
            "- **Processed data**: `data/processed/<kind>/<state>/` holds the finished",
            "  products under their state names; `MANIFEST.tsv` lists every file.",
            "",
        ]
    )

    return "\n".join(lines)


def write_root_readme(output_root: Path | str) -> Path:
    """Generate and write README.md for an output root directory."""
    root = Path(output_root)
    root.mkdir(parents=True, exist_ok=True)
    readme_path = root / "README.md"
    readme_path.write_text(generate_root_readme(root), encoding="utf-8")
    return readme_path


def generate_product_readme(
    product_dir: Path | str, product_type: str | None = None
) -> str:
    """Generate README.md content for a specific product folder, listing runs from manifests."""
    dir_path = Path(product_dir)
    p_type = product_type or dir_path.name
    desc = PRODUCT_DESCRIPTIONS.get(p_type, f"Scientific data products for '{p_type}'.")

    lines = [
        f"# Product: {p_type}",
        "",
        f"{desc}",
        "",
        "## Schema",
        "",
        f"Each run directory under `{p_type}/` contains an immutable `manifest.json` adhering to",
        "schema version 1. It records:",
        "- `scientific_identity`: Canonical full-precision parameter settings.",
        "- `scientific_id_sha256`: Full 64-hex SHA-256 digest of canonical identity JSON.",
        "- `parents`: Upstream product dependencies and digests.",
        "- `artifacts`: Produced data files and their SHA-256 checksums.",
        "- `run_fields`: Execution host and Slurm/local run identifier.",
        "",
        "## Recorded Runs",
        "",
    ]

    manifests: list[tuple[str, Manifest]] = []
    if dir_path.exists() and dir_path.is_dir():
        for child in sorted(dir_path.iterdir()):
            if child.is_dir():
                manifest_file = child / "manifest.json"
                if manifest_file.exists():
                    try:
                        m = read_manifest(manifest_file)
                        manifests.append((child.name, m))
                    except (json.JSONDecodeError, KeyError, ValueError, OSError):
                        pass

    if manifests:
        lines.append(
            "| Directory / Label | Short Hash | Host | Run ID | Created (UTC) | Artifacts |"
        )
        lines.append("| :--- | :--- | :--- | :--- | :--- | :--- |")
        for folder_name, m in manifests:
            short_h = f"`{m.short_hash}`"
            host = m.run_fields.get("host", "–")
            run = m.run_fields.get("run", "–")
            created = m.created_at
            art_count = f"{len(m.artifacts)} files"
            lines.append(
                f"| `{folder_name}` | {short_h} | {host} | {run} | {created} | {art_count} |"
            )
        full_runs = [
            (label, manifest.scientific_identity["full_graph_counts"])
            for label, manifest in manifests
            if "full_graph_counts" in manifest.scientific_identity
        ]
        if full_runs:
            lines.extend(
                [
                    "",
                    "## Full graph component handling",
                    "",
                    (
                        "Each `graph=full` product verifies and records that all input "
                        "vertices and edges were retained in one connected component:"
                    ),
                    "",
                ]
            )
            for label, counts in full_runs:
                lines.append(
                    f"- `{label}`: {counts['selected_vertices']}/"
                    f"{counts['input_vertices']} vertices and "
                    f"{counts['selected_edges']}/{counts['input_edges']} edges; "
                    f"{counts['components']} component(s), "
                    f"{counts['excluded_vertices']} excluded vertices."
                )
    else:
        lines.append("_No runs recorded yet._")

    lines.append("")
    return "\n".join(lines)


def write_product_readme(
    product_dir: Path | str, product_type: str | None = None
) -> Path:
    """Generate and write README.md for a specific product directory."""
    pdir = Path(product_dir)
    pdir.mkdir(parents=True, exist_ok=True)
    readme_path = pdir / "README.md"
    readme_path.write_text(
        generate_product_readme(pdir, product_type), encoding="utf-8"
    )
    return readme_path
